<script setup>
import {computed,ref,watch} from 'vue'
import {sceneFor,traceFacts} from './visual-data.js'
const props=defineProps({snapshot:Object,reference:Object,checkpoint:{type:Number,default:-1}})
const scene=computed(()=>sceneFor(props.snapshot))
const facts=computed(()=>scene.value.facts||traceFacts(props.snapshot?.result.trace))
const referenceFacts=computed(()=>traceFacts(props.reference?.result.trace))
const expanded=ref(false),selected=ref(-1)
watch(()=>props.snapshot,()=>{selected.value=-1})
const changed=fact=>Boolean(props.reference)&&referenceFacts.value.find(f=>f.label===fact.label)?.value!==fact.value
const bytes=computed(()=>Array.from(scene.value.body||'').slice(0,32))
const clipped=value=>{const text=String(value);return text.length>60?text.slice(0,57)+'…':text||'(absent)'}
const byteLabel=char=>char==='\r'?'CR':char==='\n'?'LF':char===' '?'·':char
const percentage=(end,total)=>Math.max(0,Math.min(100,Number(end)/(total||1)*100))
</script>
<template>
 <div v-if="!snapshot" class="scene-waiting"><div class="waiting-route"><span>① Your input</span><i>→</i><span>② Interpretation</span><i>→</i><span>③ Evidence</span></div><p>Try a ready example. Watch its route through the model appear here.</p></div>
 <div v-else class="model-scene" :data-scene="scene.kind" :key="snapshot.id">
  <p class="scene-question">{{scene.question}}</p>
  <template v-if="scene.kind==='request'">
   <div class="route-request"><span class="http-badge">{{scene.method}}</span><code>{{scene.path}}</code><span>→ route lookup</span></div><div class="route-map"><div v-for="route in scene.routes" :key="route.path" class="route-match" :class="{matched:route.matched}"><span>{{route.matched?'→':'·'}}</span><code>{{route.path}}</code><strong>{{route.name}}</strong><span>{{route.matched?'Selected':'Not selected'}}</span></div></div><p v-if="!scene.routes.some(r=>r.matched)" class="scene-notice">No route in this fixture matches the requested path.</p>
  </template>
  <template v-else-if="scene.kind==='query'">
   <div class="query-mode"><span>{{scene.binding?'BOUND VALUE':'QUERY SOURCE'}}</span><code>{{scene.query}}</code><code v-if="scene.binding">Bound value: {{JSON.stringify(scene.boundValue)}}</code><span>{{scene.binding?'Input stays data':'Input enters the expression'}}</span></div>
   <p v-if="scene.error" class="scene-notice">Parser stopped: {{scene.error}}</p><template v-else><div class="query-count"><strong>{{scene.rows.filter(r=>r.matched).length}}</strong><span>of {{scene.rows.length}} fictional records matched</span><span class="scene-legend">● returned · ○ filtered out</span></div><div class="query-records"><button v-for="(row,i) in scene.rows" :key="row.name" :class="{'record-matched':row.matched,'record-private':!row.released&&row.matched}" :aria-pressed="selected===i" @click="selected=selected===i?-1:i"><span class="record-dot">{{row.matched?'●':'○'}}</span><strong>{{row.name}}</strong><span>{{row.category}}</span><span>{{row.released?'Released':'Unreleased'}}</span><b>{{row.matched?'IN':'OUT'}}</b></button></div><p v-if="selected>=0" class="scene-detail">{{scene.rows[selected].name}} · category={{scene.rows[selected].category}} · released={{scene.rows[selected].released}} · {{scene.rows[selected].matched?'Included in this result':'Filtered out by this interpretation'}}.</p></template>
  </template>
  <template v-else-if="scene.kind==='path'">
   <div class="path-transform"><div><span>Sent</span><code>{{scene.input}}</code></div><i>↓ decode</i><div><span>Decoded</span><code>{{scene.decoded}}</code></div><i>↓ resolve</i><div :class="{'outside-root':!scene.allowed}"><span>Resolved</span><code>{{scene.resolved}}</code></div></div><div class="folder-map"><div class="folder-parent">▾ /srv</div><div class="permitted-folder"><span>▾ images <small>permitted root</small></span><span :class="{selected:scene.resolved==='/srv/images/cat.png'}">▧ cat.png {{scene.resolved==='/srv/images/cat.png'?'← selected':''}}</span></div><div class="private-file" :class="{selected:scene.resolved==='/srv/notes.txt'}">▤ notes.txt <span>{{scene.resolved==='/srv/notes.txt'?'← selected path':'outside image root'}}</span></div></div><p class="scene-notice" :class="{protected:scene.blocked}">{{scene.blocked?'The root check stops this file access.':scene.allowed?'The resolved path stays inside the permitted root.':'The path left the permitted root. This fixture does not enforce containment.'}}</p>
  </template>
  <template v-else-if="scene.kind==='ownership'">
   <div class="ownership-map"><div class="identity-card"><span class="person-symbol">◎</span><small>SESSION ACCOUNT</small><strong>{{scene.actor}}</strong></div><div class="ownership-gate" :class="{mismatch:scene.actor!==scene.owner}"><span>{{scene.checked?'⌑':'⋯'}}</span><strong>{{scene.checked?'Owner check':'Login check only'}}</strong><small>{{scene.actor===scene.owner?'Same account':'Different accounts'}}</small></div><div class="identity-card"><span class="person-symbol">▤</span><small>{{scene.resource}}</small><strong>{{scene.owner}}</strong><small>record owner</small></div></div><div class="access-route" :class="{stopped:!scene.granted}"><span>{{scene.actor}}</span><i>{{scene.granted?'────────→':'─────⌑'}}</i><strong>{{scene.granted?'Record returned':'Access stopped'}}</strong></div>
  </template>
  <template v-else-if="scene.kind==='race'">
   <div class="race-label"><span>Execution order · no real elapsed time</span><strong>{{scene.atomic?'Recheck at commit':'Earlier checks are trusted'}}</strong></div><div class="race-grid"><div class="race-track" v-for="actor in ['A','B']" :key="actor"><span class="race-actor">{{actor}}</span><div v-for="(event,i) in scene.events" :key="i" class="race-slot"><button v-if="event.actor===actor" :aria-pressed="selected===i" :class="{committed:event.committed}" @click="selected=i"><small>{{i+1}}</small>{{event.operation==='check'?'Check':event.committed?'Apply':'Stop'}}</button><span v-else>·</span></div></div></div><div class="coupon-state"><span>Committed discounts</span><strong>{{scene.count}}</strong><span v-for="i in scene.count" :key="i" class="coupon-token">coupon</span></div><p v-if="selected>=0" class="scene-detail">{{scene.events[selected].message}} · used={{scene.events[selected].before}} → {{scene.events[selected].after}} · commits={{scene.events[selected].count}}.</p><p v-else class="scene-detail">Click an operation to inspect the shared state at that point.</p>
  </template>
  <template v-else-if="scene.kind==='framing'">
   <p v-if="scene.blocked" class="scene-notice protected">Ambiguous framing is rejected. These are the parser calculations, not consumed requests.</p><div class="byte-lane" v-for="[label,end] in [['Front end',scene.front],['Backend',scene.back]]" :key="label"><div><strong>{{label}}</strong><span>{{end===null?'Boundary unknown':end+' / '+scene.available+' bytes'}}</span></div><div class="byte-bar"><span :style="{width:percentage(end,scene.available)+'%'}"></span><i v-if="end!==null" :style="{left:percentage(end,scene.available)+'%'}"></i></div><div class="byte-cells"><span v-for="(char,i) in bytes" :key="i" :class="{consumed:end!==null&&i<end,boundary:i===end}" :title="'Byte '+i">{{byteLabel(char)}}</span></div></div><p class="scene-detail">{{scene.available>32?'First 32 bytes shown. ':''}}Positions start at byte 0. CR and LF each occupy one ASCII byte. {{scene.front===null||scene.back===null?'At least one boundary is unknown; no mismatch is confirmed.':scene.front>scene.available||scene.back>scene.available?'A boundary exceeds available bytes; framing is incomplete.':scene.front!==scene.back?'The two known end positions differ.':'Both parsers have the same end position.'}}</p>
  </template>
  <template v-else-if="scene.kind==='cache'">
   <div class="cache-flow"><div class="cache-client"><span>① First request</span><code>{{scene.key}}</code></div><i>↓ stores</i><div class="cache-entry"><span>▣ Cache entry</span><code>{{scene.stored}}</code></div><i>{{scene.reused?'↓ same key · reuse':'↓ different key · separate copy'}}</i><div class="cache-client clean-client"><span>② Clean client</span><code>{{scene.cleanKey}}</code><strong>{{scene.clean}}</strong></div></div>
  </template>
  <template v-else-if="scene.kind==='dom'">
   <div class="dom-columns"><div><span class="scene-small-label">SOURCE GIVEN TO THE PARSER</span><code>{{scene.source}}</code></div><div><span class="scene-small-label">INERT PARSED ELEMENTS</span><div v-for="(node,i) in scene.nodes" :key="i" class="dom-node" :style="{marginLeft:Math.min(node.depth||0,4)*12+'px'}"><span>◇</span><code>{{typeof node==='string'?node:node.label}}</code></div></div></div><div class="dom-text"><span>Text content</span><code>{{scene.text||'(empty)'}}</code></div><p class="scene-detail">Element creation is visible here. Scripts, handlers, requests, and navigation never run.</p>
  </template>
  <template v-else-if="scene.kind==='transform'">
   <div class="transformation-chain"><template v-for="(stage,i) in scene.stages" :key="i"><i v-if="i">↓</i><div :class="{'stage-focused':checkpoint===i}"><span>{{String(i+1).padStart(2,'0')}} · {{stage.label}}</span><code>{{stage.value||'(empty)'}}</code></div></template></div>
  </template>
  <template v-else-if="scene.kind==='session'">
   <div class="session-cookie"><span>Cookie sent</span><code>{{scene.cookie||'(absent)'}}</code></div><div class="session-table"><div v-for="row in scene.sessions" :key="row.cookie" :class="{matched:row.cookie===scene.cookie}"><code>{{row.cookie}}</code><span>→</span><strong>{{row.identity}}</strong></div></div><div class="session-result"><span>Session lookup</span><strong>{{scene.identity}}</strong><code>{{scene.path}}</code></div>
  </template>
  <template v-else-if="scene.kind==='network'">
   <div class="network-map"><div class="network-browser"><span>▣</span><strong>Your browser</strong><small>supplies a value</small></div><i>→</i><div class="network-server"><span>▤</span><strong>Application server</strong><small>uses its own network position</small></div></div><div class="network-hop" v-for="(hop,i) in scene.hops" :key="i"><span>{{i+1}} · {{hop.label}}</span><code>{{hop.value}}</code></div><p class="scene-notice" :class="{protected:scene.blocked}">{{scene.blocked?'Destination policy stops the modeled fetch.':scene.policy}}</p><p class="scene-detail">{{scene.policy}}. These are virtual destinations; this diagram never contacts them.</p>
  </template>
  <template v-else-if="scene.kind==='money'">
   <div class="money-equation"><code>{{scene.quantity}} × ${{scene.unit}}</code><span>=</span><strong>${{scene.total}}</strong><small>calculated cost</small></div><div class="wallets"><div><span>Before</span><strong>${{scene.before}}</strong><i :style="{width:scene.before/Math.max(scene.before,scene.after)*100+'%'}"></i></div><span>→</span><div :class="{'balance-changed':scene.before!==scene.after}"><span>After</span><strong>${{scene.after}}</strong><i :style="{width:Math.max(0,Math.min(100,scene.after/Math.max(scene.before,scene.after)*100))+'%'}"></i></div></div><p class="scene-notice" :class="{protected:!scene.accepted}">{{scene.accepted?'The calculated total was applied to the fictional balance.':'Checkout is rejected; the balance stays unchanged.'}}</p>
  </template>
  <template v-else>
   <div class="source-pills"><span class="scene-small-label">INPUT SNAPSHOT</span><code v-for="(value,key) in snapshot.values" :key="key" :title="String(value)">{{key}}={{clipped(value)}}</code><span v-if="snapshot.safe" class="policy-pill">Boundary enforced</span></div><div class="fact-connector">↓ reported model checkpoints</div>
   <div class="decision-facts"><button v-for="(fact,i) in facts.slice(0,expanded||checkpoint>=6?facts.length:6)" :key="i" :class="{'fact-changed':changed(fact),'fact-focused':checkpoint===i}" :aria-pressed="selected===i" @click="selected=selected===i?-1:i"><span class="fact-number">{{String(i+1).padStart(2,'0')}}</span><span><strong>{{fact.label}}</strong><code>{{fact.value||'(empty)'}}</code></span><span v-if="changed(fact)" class="fact-change-tag">changed</span><span v-else class="fact-point">{{['true','yes'].includes(fact.value)?'●':['false','no'].includes(fact.value)?'○':'◇'}}</span></button></div><button v-if="facts.length>6" class="quiet-button scene-expand" @click="expanded=!expanded">{{expanded?'Show fewer checkpoints':'Show all '+facts.length+' checkpoints'}}</button><div class="fact-connector">↓ observed result</div><div class="fact-observation">{{snapshot.result.output}}</div><p v-if="selected>=0" class="scene-detail">{{facts[selected].label}} is a value reported by this model. {{changed(facts[selected])?'It differs from your comparison request.':'Compare this checkpoint with a different request to isolate its effect.'}}</p>
  </template>
 </div>
</template>
